mapper.select:
SELECT ri.recipe_ing_id, ri.recipe_id, ri.master_ingredient_id, ri.alt_ingredient_id, alt.name AS alt_ingredient_name, ri.category_id, ri.name, ri.quantity, ri.unit, ri.type_code, ri.is_optional, COALESCE(ic.is_sauce, false) AS is_sauce FROM public.recipe_ingredient ri LEFT JOIN public.ingredient_category ic ON ri.category_id = ic.category_id LEFT JOIN public.ingredient_master alt ON ri.alt_ingredient_id = alt.master_ingredient_id WHERE ri.recipe_id IN
#{id}
ORDER BY ri.recipe_id ASC, ri.type_code ASC, ri.recipe_ing_id ASC
